import java.nio.file.*;import java.security.*;
class GenerateServiceKeys {public static void main(String[] a)throws Exception{String prefix=a.length>1?a[1]:"core";if(!prefix.equals("core")&&!prefix.equals("community"))throw new IllegalArgumentException();Path p=Path.of(a[0]);Files.createDirectories(p);if(Files.exists(p.resolve(prefix+"-private.pk8")))throw new IllegalStateException("Do not replace existing keys");KeyPairGenerator g=KeyPairGenerator.getInstance("RSA");g.initialize(3072);KeyPair k=g.generateKeyPair();Files.write(p.resolve(prefix+"-private.pk8"),k.getPrivate().getEncoded(),StandardOpenOption.CREATE_NEW);Files.write(p.resolve(prefix+"-public.der"),k.getPublic().getEncoded(),StandardOpenOption.CREATE_NEW);}}
